import re
import xml.etree.ElementTree as ET
BASE = "https://le.utah.gov/xcode/"
SKIP = {"histories", "catchline", "enddate", "effdate"}
BREAK = {"eol", "center", "right", "row", "format"}

NL = chr(0)   # a structural line break; the XML's own newlines are only whitespace

def render(e, out):
    for c in e:
        if c.tag in SKIP:
            pass
        elif c.tag == "subsection":
            lab = re.findall(r"\([^()]*\)", c.get("number") or "")
            out.append(NL + (lab[-1] + " " if lab else ""))
            out.append(c.text or "")
            render(c, out)
        elif c.tag == "tab":
            out.append(" ")
        elif c.tag == "cell":
            out.append(" " + (c.text or ""))
            render(c, out)
            out.append(" ")
        else:
            if c.tag in BREAK:
                out.append(NL)
            out.append(c.text or "")
            render(c, out)
            if c.tag in BREAK:
                out.append(NL)
        out.append(c.tail or "")

def section_text(s):
    out = [s.text or ""]
    render(s, out)
    lines = [" ".join(l.split()) for l in "".join(out).split(NL)]
    hist = "; ".join(" ".join("".join(h.itertext()).split()) for h in s.iter("history"))
    return "\n".join([l for l in lines if l] + (["[" + hist + "]"] if hist else []))

def sections():
    _, idx = fetch(BASE + "code.html")
    v = re.search(r'versionDefault\s*=\s*"([^"]+)"', idx).group(1)
    _, top = fetch(BASE + v + ".html")
    titles = []
    for t, tv in re.findall(r'href="Title(\w+)/\w+\.html\?v=(C[\w-]+)"', top):
        if (t, tv) not in titles:
            titles.append((t, tv))
    log("titles=%d" % len(titles))
    for t, tv in titles:
        url = "%sTitle%s/%s.xml" % (BASE, t, tv)
        try:
            _, body = fetch(url)
            if isinstance(body, bytes):
                body = body.decode("utf-8", "replace")
            root = ET.fromstring(body[body.find("<title"):])
        except Exception as e:
            log("title %s failed %r" % (t, e))
            continue
        groups = {}
        for s in root.iter("section"):
            groups.setdefault(s.get("number"), []).append(s)
        n = later = 0
        for sid, vs in groups.items():
            if len(vs) > 1:
                cur = [s for s in vs if s.find("effdate") is None] or vs
                later += len(vs) - 1
                s = cur[0]
            else:
                s = vs[0]
            text = section_text(s)
            if not sid or not text:
                continue
            n += 1
            head = " ".join((s.findtext("catchline") or "").split()).rstrip(".")
            yield {"id": sid, "heading": head, "text": text,
                   "url": url}
        log("title %s sections=%d%s" % (t, n, " (later versions skipped: %d)" % later if later else ""))
